// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);

        // Try a call from a non-owner (address(this) is owner, so use another address)
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 0); // ensure sufficient balance for tx costs (not needed)
        vm.prank(nonOwner);
        bool ok;
        try c.withdrawAll(nonOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: reverts, so ok == false. Buggy: does not revert, so ok == true.
        assertTrue(!ok);
    }
}
